-a5e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"usuario","tipo":"texto","contenido":"Ok aplica los cambios por favor","media_path":null,"creado_en":"2026-05-05T22:54:51.524315+00:00","wa_msg_id":"2ACFFE76F9105E16DB82"}, {"id":"acd1ab04-1429-4ced-899c-2c667ade01ce","cuenta_id":"87d27b40-b7c5-4bd7-9ab6-a5e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"usuario","tipo":"texto","contenido":"Y la información del negocio cámbiala y actualízala por favor","media_path":null,"creado_en":"2026-05-05T22:55:23.965443+00:00","wa_msg_id":"2A4ECF14A869E072D31B"}, {"id":"87dc773e-6631-4adf-9208-857fdb947e7e","cuenta_id":"87d27b40-b7c5-4bd7-9ab6-a5e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"asistente","tipo":"texto","contenido":"Listo, he actualizado el perfil del agente. Ahora Toretto es un **Asesor de agencia de marketing**, y el mensaje de bienvenida refleja que ofrecemos agentes de WhatsApp con precios desde 50 mil pesos en adelante.\n\n¿Hay algo más en lo que te pueda ayudar?","media_path":null,"creado_en":"2026-05-05T22:55:27.126361+00:00","wa_msg_id":null}, {"id":"d3a87691-e316-46b1-8b3d-4f6d992c925e","cuenta_id":"ba5c3e92-dd0b-4d98-addc-3eb43509b3d5","conversacion_id":"495335c3-f181-4390-b761-911a48df6f50","rol":"asistente","tipo":"texto","contenido":"¿Qué te parece? Si querés más información sobre los eventos o precios, ¡dímelo!","media_path":null,"creado_en":"2026-05-05T23:49:39.107186+00:00","wa_msg_id":"3EB0B780775F699A947593"}, {"id":"bbde6811-d696-43ef-a515-bb300a09579d","cuenta_id":"ba5c3e92-dd0b-4d98-addc-3eb43509b3d5","conversacion_id":"495335c3-f181-4390-b761-911a48df6f50","rol":"usuario","tipo":"texto","contenido":"Envíame otra","media_path":null,"creado_en":"2026-05-05T23:49:58.62542+00:00","wa_msg_id":"2AAB91AB1D8B0CD02E95"}, {"id":"5a722d77-1a71-4cdd-8503-bd9a9b286713","cuenta_id":"48dc2bd8-d710-488a-9a06-5feab2993007","conversacion_id":"029d5d17-aefa-483b-8577-fe5b6b111ed