e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"asistente","tipo":"texto","contenido":"Voy a actualizar el nombre del agente a \"BLENDER\".","media_path":null,"creado_en":"2026-05-05T18:58:50.2571+00:00","wa_msg_id":"3EB0BDCDB5F1E2720BDFA3"}, {"id":"91860fdb-b58c-4527-a20c-b819ba68375e","cuenta_id":"87d27b40-b7c5-4bd7-9ab6-a5e44790eeac","conversacion_id":"0e9f91dd-006c-40f1-9d24-eb0c0a95d693","rol":"asistente","tipo":"texto","contenido":"Sí, tenemos disponible el **Carro Volador 2026** por **189,000,000 COP**. Es un modelo innovador y único.","media_path":null,"creado_en":"2026-05-05T18:59:55.733247+00:00","wa_msg_id":"3EB0D81D13DBDF6D35BFD3"}, {"id":"3ce3a336-5593-4ad0-88b2-3b6470b64e4f","cuenta_id":"87d27b40-b7c5-4bd7-9ab6-a5e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"usuario","tipo":"texto","contenido":"Tú lo puedes consultar aparece en la información de contacto de nuestros leads","media_path":null,"creado_en":"2026-05-05T20:09:20.220557+00:00","wa_msg_id":"2A4A9568EE6593EC1981"}, {"id":"e9fc6403-cf70-402e-b40e-9900db1612d5","cuenta_id":"87d27b40-b7c5-4bd7-9ab6-a5e44790eeac","conversacion_id":"4e9de144-174d-483b-a32a-7ef1a8965683","rol":"asistente","tipo":"texto","contenido":"El mensaje a Jesús fue enviado con éxito, y la conversación ha pasado a modo HUMANO, así que la IA no responderá automáticamente.\n\n¿Hay algo más en lo que te pueda ayudar?","media_path":null,"creado_en":"2026-05-05T20:09:26.243818+00:00","wa_msg_id":null}, {"id":"c5247762-27bd-4f56-8d38-0782e3eb96df","cuenta_id":"48dc2bd8-d710-488a-9a06-5feab2993007","conversacion_id":"1d7b19a2-218c-4d9a-ba10-277976a1cd66","rol":"usuario","tipo":"audio","contenido":"Respóndeme con un audio que no pueda escuchar, no puedo leer bien","media_path":"48dc2bd8-d710-488a-9a06-5feab2993007/1777832125892_d069a5f7.ogg","creado_en":"2026-05-03T18:15:28.819771+00:00","wa_msg_id":"2A8DD515CD40B3289244"}, {"id":"9c1d6ecd-0bfd-4199-bd1f-8f824f29e7f1","cuenta_id